"""Repayment statement documents, generated by the (mock) lender from its own loan records.

This stands in for the lender's document service: the assistant only requests a statement; the
lender produces the official PDF in a fixed format from the system of record, stores it and serves
it back by reference. Every page is marked as synthetic demo data.
"""
from __future__ import annotations

import hashlib
import uuid
from dataclasses import dataclass
from datetime import date, datetime, timezone
from pathlib import Path

from fpdf import FPDF

from .common import ROOT

DOCS_DIR = ROOT / "data" / "documents"
PRODUCT_NAME = {"HOME_LOAN": "Home loan", "LAP": "Loan against property", "PERSONAL_LOAN": "Personal loan"}


def fy_bounds(fy: str) -> tuple[date, date]:
    """'2025-26' -> 1 Apr 2025 .. 31 Mar 2026."""
    start = int(fy.split("-")[0])
    return date(start, 4, 1), date(start + 1, 3, 31)


def _rs(x: float) -> str:
    """Indian digit grouping: 1234567.8 -> Rs 12,34,567.80"""
    neg, x = x < 0, abs(round(x, 2))
    whole, frac = f"{x:.2f}".split(".")
    head, tail = whole[:-3], whole[-3:]
    groups = []
    while len(head) > 2:
        groups.insert(0, head[-2:])
        head = head[:-2]
    if head:
        groups.insert(0, head)
    return f"{'-' if neg else ''}Rs {','.join(groups + [tail]) if groups else tail}.{frac}"


def _d(iso: str | None) -> str:
    return date.fromisoformat(iso[:10]).strftime("%d %b %Y") if iso else "-"


@dataclass
class Statement:
    document_id: str
    loan_id: str
    customer_id: str
    financial_year: str
    file_name: str
    path: Path
    size_bytes: int
    sha256: str
    generated_at: str
    totals: dict

    def public(self) -> dict:
        return {k: v for k, v in self.__dict__.items() if k != "path"}


def build_statement(loan: dict, customer: dict | None, charges: list[dict], fy: str, as_of: date) -> Statement:
    start, end = fy_bounds(fy)
    end_eff = min(end, as_of)
    rows = [r for r in loan["schedule"] if start.isoformat() <= r["due_date"] <= end_eff.isoformat()]
    prepayments = [e for r in loan["schedule"] for e in r["events"]
                   if e["type"] == "PART_PREPAYMENT" and start.isoformat() <= e["on"] <= end_eff.isoformat()]
    period_charges = [c for c in charges if start.isoformat() <= c["levied_on"] <= end_eff.isoformat()]
    paid = [r for r in rows if r["status"] in ("PAID", "PAID_LATE")]
    totals = {
        "period_start": start.isoformat(), "period_end": end_eff.isoformat(),
        "instalments_due": len(rows), "instalments_paid": len(paid),
        "instalments_overdue": sum(r["status"] == "OVERDUE" for r in rows),
        "emi_paid": round(sum(r["emi"] for r in paid), 2),
        "principal_paid": round(sum(r["principal"] for r in paid), 2),
        "interest_paid": round(sum(r["interest"] for r in paid), 2),
        "part_prepayments": round(sum(e["amount"] for e in prepayments), 2),
        "charges_paid": round(sum(c["total"] for c in period_charges if c["status"] == "PAID"), 2),
        "charges_waived": round(sum(c["total"] for c in period_charges if c["status"] == "WAIVED"), 2),
        "opening_principal": rows[0]["opening_principal"] if rows else None,
        "closing_principal": rows[-1]["closing_principal"] if rows else None,
    }

    pdf = FPDF(format="A4")
    pdf.set_auto_page_break(auto=True, margin=18)
    pdf.set_title(f"Repayment statement {loan['loan_id']} FY {fy}")
    name = f"{customer['first_name']} {customer['last_name']}" if customer else loan["customer_id"]

    def footer():
        pdf.set_y(-14)
        pdf.set_font("Helvetica", "I", 7)
        pdf.set_text_color(130)
        pdf.cell(0, 5, "SAMPLE - synthetic demonstration data, not a real bank document. "
                       f"Generated {datetime.now(timezone.utc).strftime('%d %b %Y %H:%M UTC')}.", align="C")

    pdf.footer = footer  # type: ignore[method-assign]
    pdf.add_page()
    pdf.set_font("Helvetica", "B", 16)
    pdf.set_text_color(29, 78, 216)
    pdf.cell(0, 9, "Repayment Statement", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "", 9)
    pdf.set_text_color(90)
    pdf.cell(0, 5, f"Financial year {fy}  |  {_d(start.isoformat())} to {_d(end_eff.isoformat())}"
                   + ("  (year to date)" if end_eff < end else ""), new_x="LMARGIN", new_y="NEXT")
    pdf.ln(4)

    pdf.set_text_color(20)
    info = [("Customer", f"{name} ({loan['customer_id']})"), ("Loan account", loan["loan_id"]),
            ("Product", PRODUCT_NAME.get(loan["product"], loan["product"])),
            ("Sanctioned amount", _rs(loan["sanctioned_amount"])),
            ("Interest", f"{loan['rate_type'].title()}, currently {loan['current_rate_pct']}% p.a."),
            ("Disbursed on", _d(loan["disbursal_date"]))]
    for label, value in info:
        pdf.set_font("Helvetica", "", 9)
        pdf.cell(40, 6, label)
        pdf.set_font("Helvetica", "B", 9)
        pdf.cell(0, 6, value, new_x="LMARGIN", new_y="NEXT")
    pdf.ln(3)

    pdf.set_fill_color(231, 237, 253)
    pdf.set_font("Helvetica", "B", 10)
    pdf.cell(0, 7, "  Summary for the period", fill=True, new_x="LMARGIN", new_y="NEXT")
    summary = [
        ("Instalments due / paid", f"{totals['instalments_due']} / {totals['instalments_paid']}"
                                   + (f"  ({totals['instalments_overdue']} overdue)" if totals["instalments_overdue"] else "")),
        ("Opening principal", _rs(totals["opening_principal"]) if rows else "-"),
        ("Principal repaid", _rs(totals["principal_paid"])),
        ("Interest paid", _rs(totals["interest_paid"])),
        ("Part-prepayments", _rs(totals["part_prepayments"])),
        ("Charges paid (incl. GST)", _rs(totals["charges_paid"])),
        ("Closing principal", _rs(totals["closing_principal"]) if rows else "-"),
    ]
    for label, value in summary:
        pdf.set_font("Helvetica", "", 9)
        pdf.cell(70, 6, "  " + label)
        pdf.set_font("Helvetica", "B", 9)
        pdf.cell(0, 6, value, new_x="LMARGIN", new_y="NEXT")
    pdf.ln(4)

    cols = [("#", 9), ("Due date", 24), ("EMI", 26), ("Principal", 26), ("Interest", 26), ("Balance", 30), ("Status", 22), ("Paid on", 23)]
    pdf.set_font("Helvetica", "B", 8)
    pdf.set_fill_color(240, 242, 245)
    for title, w in cols:
        pdf.cell(w, 6, title, border="B", fill=True, align="R" if title in ("EMI", "Principal", "Interest", "Balance") else "L")
    pdf.ln()
    pdf.set_font("Helvetica", "", 8)
    for r in rows:
        status = "  " + {"PAID": "Paid", "PAID_LATE": f"Paid late ({r['days_late']}d)", "OVERDUE": "Overdue"}.get(r["status"], r["status"].title())  # leading gap after Balance
        values = [str(r["number"]), _d(r["due_date"]), _rs(r["emi"])[3:], _rs(r["principal"])[3:], _rs(r["interest"])[3:],
                  _rs(r["closing_principal"])[3:], status, _d(r["paid_on"])]
        for (title, w), v in zip(cols, values):
            pdf.cell(w, 5.5, v, align="R" if title in ("EMI", "Principal", "Interest", "Balance") else "L")
        pdf.ln()
    if not rows:
        pdf.cell(0, 6, "No instalments fell due in this period.", new_x="LMARGIN", new_y="NEXT")

    if prepayments or period_charges:
        pdf.ln(4)
        pdf.set_font("Helvetica", "B", 9)
        pdf.cell(0, 6, "Other transactions", new_x="LMARGIN", new_y="NEXT")
        pdf.set_font("Helvetica", "", 8)
        for e in prepayments:
            pdf.cell(0, 5, f"{_d(e['on'])}   Part-prepayment   {_rs(e['amount'])}   ({e['mode'].replace('_', ' ').lower()})",
                     new_x="LMARGIN", new_y="NEXT")
        for c in period_charges:
            pdf.cell(0, 5, f"{_d(c['levied_on'])}   {c['type'].replace('_', ' ').title()}   {_rs(c['total'])}   "
                           f"{c['status'].lower()}" + (f" - {c['waiver_reason']}" if c.get("waiver_reason") else ""),
                     new_x="LMARGIN", new_y="NEXT")

    pdf.ln(5)
    pdf.set_font("Helvetica", "", 8)
    pdf.set_text_color(90)
    pdf.multi_cell(0, 4.5, "Figures are taken from the loan management system as of "
                           f"{_d(as_of.isoformat())}. Principal and interest totals cover instalments paid in the period.")

    DOCS_DIR.mkdir(parents=True, exist_ok=True)
    document_id = f"DOC-{uuid.uuid4().hex[:12].upper()}"
    file_name = f"repayment-statement-{loan['loan_id']}-FY{fy}.pdf"
    path = DOCS_DIR / f"{document_id}.pdf"
    data = bytes(pdf.output())
    path.write_bytes(data)
    return Statement(document_id, loan["loan_id"], loan["customer_id"], fy, file_name, path, len(data),
                     hashlib.sha256(data).hexdigest(), datetime.now(timezone.utc).isoformat(), totals)
